import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './spacer.module.css'
import type { SpaceStep } from '@cascivo/core'

export interface SpacerProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Spacing token step
   *
   * @defaultValue `4`
   * @see the component manifest
   */
  size?: SpaceStep
}

export function Spacer({ size = 4, className, style, ...props }: SpacerProps) {
  return (
    <div
      role="none"
      className={cn(styles['spacer'], className)}
      style={{ ['--_spacer-size' as string]: `var(--cascivo-space-${size})`, ...style }}
      {...props}
    />
  )
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Spacer',
  description: 'Fixed-height spacing block using design token steps.',
  category: 'layout',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'size',
      default: '4',
      type: '1|2|3|4|5|6|8|10|12',
      required: false,
      description: 'Spacing token step',
    },
  ],
  tokens: ['--cascivo-space-*'],
  accessibility: { role: 'none', wcag: '2.1-AA', keyboard: [] },
  examples: [
    {
      title: 'Spacer',
      code: '<Spacer size={8} />',
      description: 'Adds vertical space between elements',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['layout', 'spacer', 'spacing'],
  intent: {
    whenToUse: [
      'Inserting a fixed vertical gap between blocks using spacing token steps',
      'Adding deliberate breathing room where margins are awkward',
    ],
    whenNotToUse: [
      'Spacing a series of siblings — use Flex with a gap instead',
      'Arbitrary one-off spacing — prefer token-based gap props',
    ],
    antiPatterns: [],
    related: [
      {
        name: 'Flex',
        relationship: 'alternative',
        reason: 'Use gap on Flex to space multiple siblings consistently',
      },
    ],
    a11yRationale: 'Empty presentational spacer with no semantic role; ignored by assistive tech.',
    flexibility: [],
  },
}
